public class VariablesDemo {
    public static void main(String[] args) {
        String student = "Safayet";
        int courses = 5;
        int creditsPerCourse = 3;
        double feePerCredit = 1500.0;
        boolean enrolled = true;

        int totalCredits = courses * creditsPerCourse;
        double tuition = totalCredits * feePerCredit;

        System.out.printf("Student: %s%n", student);
        System.out.printf("Credits: %d%n", totalCredits);
        System.out.printf("Tuition: %.2f%n", tuition);
        System.out.printf("Enrolled: %b%n", enrolled);
    }
}

