public class MethodsDemo {
    static int findIndex(int[] numbers, int target) {
        for (int i = 0; i < numbers.length; i++) {
            if (numbers[i] == target) {
                return i;
            }
        }
        return -1;
    }

    static String normalizeName(String value) {
        return value.trim().toLowerCase();
    }

    public static void main(String[] args) {
        int[] scores = {70, 85, 91, 66};
        System.out.println("Index: " + findIndex(scores, 91));
        System.out.println("Name: " + normalizeName("  Java Student  "));
    }
}

class Student {
    private final String name;
    private int credits;

    Student(String name, int credits) {
        this.name = name;
        setCredits(credits);
    }

    public String getName() {
        return name;
    }

    public int getCredits() {
        return credits;
    }

    public void setCredits(int credits) {
        if (credits < 0) {
            throw new IllegalArgumentException("Credits cannot be negative");
        }
        this.credits = credits;
    }
}

public class StudentDemo {
    public static void main(String[] args) {
        Student student = new Student("Safayet", 15);
        student.setCredits(18);
        System.out.println(student.getName() + ": " + student.getCredits());
    }
}

interface Payable {
    double calculatePay();
}

abstract class Employee implements Payable {
    protected final String name;

    Employee(String name) {
        this.name = name;
    }
}

class FullTimeEmployee extends Employee {
    FullTimeEmployee(String name) {
        super(name);
    }

    @Override
    public double calculatePay() {
        return 40000;
    }
}

class ContractEmployee extends Employee {
    ContractEmployee(String name) {
        super(name);
    }

    @Override
    public double calculatePay() {
        return 20000;
    }
}

public class PolymorphismDemo {
    public static void main(String[] args) {
        Payable[] workers = {
            new FullTimeEmployee("A"),
            new ContractEmployee("B")
        };
        for (Payable worker : workers) {
            System.out.printf("Pay: %.0f%n", worker.calculatePay());
        }
    }
}

public class ExceptionDemo {
    static int validateAge(int age) {
        if (age < 0 || age > 120) {
            throw new IllegalArgumentException("Invalid age: " + age);
        }
        return age;
    }

    public static void main(String[] args) {
        int[] ages = {20, -4, 35};
        for (int age : ages) {
            try {
                System.out.println("Accepted: " + validateAge(age));
            } catch (IllegalArgumentException error) {
                System.out.println("Rejected: " + error.getMessage());
            }
        }
    }
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class CollectionsDemo {
    static <T> void showItems(List<T> items) {
        for (T item : items) {
            System.out.println(item);
        }
    }

    public static void main(String[] args) {
        List<String> names = new ArrayList<>();
        names.add("Java");
        names.add("Python");
        names.add("Java");

        Set<String> unique = new LinkedHashSet<>(names);
        Map<String, Integer> scores = new LinkedHashMap<>();
        scores.put("Java", 95);
        scores.put("Python", 87);

        System.out.println("Unique: " + unique);
        System.out.println("Java score: " + scores.get("Java"));
        showItems(List.of("Type-safe", "Generic method"));
    }
}

import java.util.Comparator;
import java.util.List;

record Result(String name, int score) {}

public class StreamDemo {
    public static void main(String[] args) {
        List<Result> results = List.of(
            new Result("A", 70),
            new Result("B", 92),
            new Result("C", 85)
        );

        List<String> topStudents = results.stream()
            .filter(item -> item.score() >= 80)
            .sorted(Comparator.comparingInt(Result::score).reversed())
            .map(Result::name)
            .toList();

        System.out.println(topStudents);
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public class FileDemo {
    public static void main(String[] args) throws IOException {
        Path file = Path.of("grades.csv");
        String data = "name,score\nJava,95\nPython,87\n";
        Files.writeString(file, data, StandardCharsets.UTF_8);

        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        for (String line : lines) {
            System.out.println(line);
        }
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class ConcurrencyDemo {
    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try {
            Future<Integer> first = executor.submit(() -> 10 + 20);
            Future<Integer> second = executor.submit(() -> 30 + 40);
            int total = first.get() + second.get();
            System.out.println("Total: " + total);
        } finally {
            executor.shutdown();
        }
    }
}

record Book(String title, int pages) {}

public class ModernJavaDemo {
    static String readingLevel(int pages) {
        return switch (pages / 100) {
            case 0 -> "Short";
            case 1, 2 -> "Medium";
            default -> "Long";
        };
    }

    public static void main(String[] args) {
        Object value = new Book("Java Notes", 240);
        if (value instanceof Book book) {
            System.out.println(book.title());
            System.out.println(readingLevel(book.pages()));
        }
    }
}

